//! Formal Sum of Trees (`B + C - A`) Multi-Path Algebraic Engine.
//!
//! Represents every file path in a tree as an element of the free abelian group `Z[A_bot]`
//! generated by content-addressed BLAKE3 hashes `ArtifactHash` (plus `ABSENT_HASH` = 0 for
//! deleted/non-existent files):
//!   `PathSum(p) = sum_i (coeff_i * hash_i)` with `sum_i coeff_i == 1`
//!
//! Normalization rules (Jujutsu Merge Algebra + Kaki et al. OOPSLA 2019 MRDTs):
//! 1. **Abelian Group Cancellation**: Like hashes have their integer coefficients summed;
//!    terms with `coeff == 0` are eliminated (`+X - X = 0`).
//! 2. **Same-Change Collapse**: If all terms with `coeff > 0` share the exact same `hash`,
//!    the entire expression collapses to `1 * hash` (e.g., `2*X - Y -> 1*X`).
//! 3. **Clean Absence Elimination**: If the normalized sum equals `1 * ABSENT_HASH`, the path
//!    is cleanly deleted and omitted from the active tree map.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const ArtifactHash = [32]u8;
pub const ABSENT_HASH: ArtifactHash = @splat(0);

pub fn computeBlake3(bytes: []const u8) ArtifactHash {
    var out: ArtifactHash = undefined;
    std.crypto.hash.Blake3.hash(bytes, &out, .{});
    return out;
}

pub fn hashEql(a: ArtifactHash, b: ArtifactHash) bool {
    return std.mem.eql(u8, &a, &b);
}

pub fn hashLessThan(_: void, a: ArtifactHash, b: ArtifactHash) bool {
    return std.mem.order(u8, &a, &b) == .lt;
}

pub const Term = struct {
    hash: ArtifactHash,
    coeff: i32,

    pub fn eql(a: Term, b: Term) bool {
        return hashEql(a.hash, b.hash) and a.coeff == b.coeff;
    }
};

/// Formal linear combination of file states at a single path: `sum(coeff_i * hash_i) == 1`.
pub const PathSum = struct {
    terms: std.ArrayList(Term) = .empty,

    pub fn deinit(self: *PathSum, allocator: Allocator) void {
        self.terms.deinit(allocator);
    }

    pub fn clone(self: PathSum, allocator: Allocator) !PathSum {
        var copy: PathSum = .{};
        try copy.terms.appendSlice(allocator, self.terms.items);
        return copy;
    }

    pub fn fromClean(allocator: Allocator, hash: ArtifactHash) !PathSum {
        var p: PathSum = .{};
        try p.terms.append(allocator, .{ .hash = hash, .coeff = 1 });
        return p;
    }

    pub fn fromAbsent(allocator: Allocator) !PathSum {
        return fromClean(allocator, ABSENT_HASH);
    }

    /// Add `scale * hash` into this formal sum without normalizing yet.
    pub fn addTermRaw(self: *PathSum, allocator: Allocator, hash: ArtifactHash, scale: i32) !void {
        if (scale == 0) return;
        for (self.terms.items) |*t| {
            if (hashEql(t.hash, hash)) {
                t.coeff = try std.math.add(i32, t.coeff, scale);
                return;
            }
        }
        try self.terms.append(allocator, .{ .hash = hash, .coeff = scale });
    }

    /// Add `scale * other` into this formal sum and normalize.
    pub fn addScaled(self: *PathSum, allocator: Allocator, other: PathSum, scale: i32) !void {
        for (other.terms.items) |t| {
            const prod = try std.math.mul(i32, t.coeff, scale);
            try self.addTermRaw(allocator, t.hash, prod);
        }
        self.normalize();
    }

    /// Canonical normalization in `Z[A_bot]`:
    /// 1. Remove zero-coefficient terms.
    /// 2. Sort terms deterministically by `ArtifactHash`.
    /// 3. Apply Same-Change Collapse: if all positive terms share a single hash `H`,
    ///    collapse the sum to `1 * H`.
    pub fn normalize(self: *PathSum) void {
        // 1. Strip zero coefficients
        var write_idx: usize = 0;
        for (self.terms.items) |t| {
            if (t.coeff != 0) {
                self.terms.items[write_idx] = t;
                write_idx += 1;
            }
        }
        self.terms.items.len = write_idx;

        // 2. Sort deterministically by hash
        const SortCtx = struct {
            pub fn lessThan(_: void, a: Term, b: Term) bool {
                return hashLessThan({}, a.hash, b.hash);
            }
        };
        std.mem.sort(Term, self.terms.items, {}, SortCtx.lessThan);

        // 3. Same-Change Collapse: if every positive term has the same hash, collapse to 1 * hash
        var unique_pos_hash: ?ArtifactHash = null;
        var all_pos_same = true;
        for (self.terms.items) |t| {
            if (t.coeff > 0) {
                if (unique_pos_hash) |uh| {
                    if (!hashEql(uh, t.hash)) {
                        all_pos_same = false;
                        break;
                    }
                } else {
                    unique_pos_hash = t.hash;
                }
            }
        }
        if (all_pos_same) {
            if (unique_pos_hash) |uh| {
                self.terms.items[0] = .{ .hash = uh, .coeff = 1 };
                self.terms.items.len = 1;
            }
        }
    }

    /// Compute 3-way merge `ours + theirs - base` (`B + C - A`) in `Z[A_bot]`.
    pub fn threeWayMerge(
        allocator: Allocator,
        base: PathSum,
        ours: PathSum,
        theirs: PathSum,
    ) !PathSum {
        var out: PathSum = .{};
        errdefer out.deinit(allocator);

        for (ours.terms.items) |t| try out.addTermRaw(allocator, t.hash, t.coeff);
        for (theirs.terms.items) |t| try out.addTermRaw(allocator, t.hash, t.coeff);
        for (base.terms.items) |t| try out.addTermRaw(allocator, t.hash, -t.coeff);
        out.normalize();
        return out;
    }

    /// Returns the single `ArtifactHash` if this path is conflict-free (`1 * H`), or `null` if conflicted.
    pub fn getCleanHash(self: PathSum) ?ArtifactHash {
        if (self.terms.items.len == 1 and self.terms.items[0].coeff == 1) {
            return self.terms.items[0].hash;
        }
        return null;
    }

    pub fn isAbsentClean(self: PathSum) bool {
        if (self.getCleanHash()) |h| {
            return hashEql(h, ABSENT_HASH);
        }
        return false;
    }

    pub fn isConflicted(self: PathSum) bool {
        return self.getCleanHash() == null;
    }

    pub fn sumCoefficients(self: PathSum) i64 {
        var total: i64 = 0;
        for (self.terms.items) |t| {
            total += t.coeff;
        }
        return total;
    }

    /// Extract `(base_hash, ours_hash, theirs_hash)` for a standard 2-sided conflict `B + C - A`.
    pub fn extractTwoSidedConflict(self: PathSum) ?struct {
        base: ArtifactHash,
        ours: ArtifactHash,
        theirs: ArtifactHash,
    } {
        if (self.terms.items.len != 3) return null;
        var base_h: ?ArtifactHash = null;
        var pos1_h: ?ArtifactHash = null;
        var pos2_h: ?ArtifactHash = null;

        for (self.terms.items) |t| {
            if (t.coeff == -1 and base_h == null) {
                base_h = t.hash;
            } else if (t.coeff == 1) {
                if (pos1_h == null) {
                    pos1_h = t.hash;
                } else if (pos2_h == null) {
                    pos2_h = t.hash;
                } else return null;
            } else {
                return null;
            }
        }
        if (base_h != null and pos1_h != null and pos2_h != null) {
            return .{ .base = base_h.?, .ours = pos1_h.?, .theirs = pos2_h.? };
        }
        return null;
    }

    pub fn eql(a: PathSum, b: PathSum) bool {
        if (a.terms.items.len != b.terms.items.len) return false;
        for (a.terms.items, b.terms.items) |ta, tb| {
            if (!ta.eql(tb)) return false;
        }
        return true;
    }
};

pub const FileMode = enum(u32) {
    regular = 0o100644,
    executable = 0o100755,
    symlink = 0o120000,

    pub fn fromGitOctal(mode_octal: u32) FileMode {
        return switch (mode_octal) {
            0o100755 => .executable,
            0o120000 => .symlink,
            else => .regular,
        };
    }
};

pub const PathEntry = struct {
    path: []u8,
    sum: PathSum,
    mode: FileMode = .regular,
};

/// Validate and canonicalize a repository-relative path:
/// - Rejects empty paths, leading `/`, Windows `\`, NUL bytes, `.vcs` internal paths, and `..` traversal components.
/// - Collapses redundant `.` segments and duplicate `//` slashes (e.g. `"./src//app.zig"` -> `"src/app.zig"`).
pub fn validateAndNormalizePath(allocator: Allocator, raw_path: []const u8) ![]u8 {
    if (raw_path.len == 0 or raw_path[0] == '/') return error.InvalidRepoPath;
    for (raw_path) |ch| {
        if (ch == 0 or ch == '\\') return error.InvalidRepoPath;
    }

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);

    var it = std.mem.splitScalar(u8, raw_path, '/');
    while (it.next()) |seg| {
        if (seg.len == 0 or std.mem.eql(u8, seg, ".")) continue;
        if (std.mem.eql(u8, seg, "..")) return error.InvalidRepoPath;
        if (std.mem.eql(u8, seg, ".vcs") or
            std.mem.eql(u8, seg, ".git") or
            std.mem.eql(u8, seg, ".vcs-link") or
            std.mem.eql(u8, seg, ".vcs-wt"))
        {
            return error.InvalidRepoPath;
        }
        if (out.items.len > 0) try out.append(allocator, '/');
        try out.appendSlice(allocator, seg);
    }

    if (out.items.len == 0) return error.InvalidRepoPath;
    return out.toOwnedSlice(allocator);
}

/// Zero-allocation check that `path` is already in canonical normalized repository path form.
pub fn isValidNormalizedPath(path: []const u8) bool {
    if (path.len == 0 or path[0] == '/' or path[path.len - 1] == '/') return false;
    var seg_start: usize = 0;
    for (path, 0..) |ch, idx| {
        if (ch == 0 or ch == '\\') return false;
        if (ch == '/') {
            const seg = path[seg_start..idx];
            if (!isValidPathSegment(seg)) return false;
            seg_start = idx + 1;
        }
    }
    return isValidPathSegment(path[seg_start..]);
}

fn isValidPathSegment(seg: []const u8) bool {
    if (seg.len == 0) return false;
    if (std.mem.eql(u8, seg, ".") or std.mem.eql(u8, seg, "..")) return false;
    if (std.mem.eql(u8, seg, ".vcs") or
        std.mem.eql(u8, seg, ".git") or
        std.mem.eql(u8, seg, ".vcs-link") or
        std.mem.eql(u8, seg, ".vcs-wt"))
    {
        return false;
    }
    return true;
}

/// Multi-path Tree Manifest mapping sorted repository paths to their `PathSum` (`Z[A_bot]`).
pub const TreeManifest = struct {
    entries: std.ArrayList(PathEntry) = .empty,

    pub fn deinit(self: *TreeManifest, allocator: Allocator) void {
        for (self.entries.items) |*e| {
            allocator.free(e.path);
            e.sum.deinit(allocator);
        }
        self.entries.deinit(allocator);
    }

    pub fn clone(self: TreeManifest, allocator: Allocator) !TreeManifest {
        var out: TreeManifest = .{};
        errdefer out.deinit(allocator);
        try out.entries.ensureTotalCapacity(allocator, self.entries.items.len);
        for (self.entries.items) |e| {
            const p_copy = try allocator.dupe(u8, e.path);
            errdefer allocator.free(p_copy);
            var s_copy = try e.sum.clone(allocator);
            errdefer s_copy.deinit(allocator);
            out.entries.appendAssumeCapacity(.{
                .path = p_copy,
                .sum = s_copy,
                .mode = e.mode,
            });
        }
        return out;
    }

    pub const LookupResult = struct {
        found: bool,
        index: usize,
    };

    pub fn findEntryIndex(self: TreeManifest, path: []const u8) LookupResult {
        var lo: usize = 0;
        var hi: usize = self.entries.items.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            switch (std.mem.order(u8, self.entries.items[mid].path, path)) {
                .lt => lo = mid + 1,
                .gt => hi = mid,
                .eq => return .{ .found = true, .index = mid },
            }
        }
        return .{ .found = false, .index = lo };
    }

    pub fn getPathSum(self: TreeManifest, path: []const u8) ?PathSum {
        const res = self.findEntryIndex(path);
        return if (res.found) self.entries.items[res.index].sum else null;
    }

    pub fn getPathMode(self: TreeManifest, path: []const u8) ?FileMode {
        const res = self.findEntryIndex(path);
        return if (res.found) self.entries.items[res.index].mode else null;
    }

    pub fn setCleanFile(self: *TreeManifest, allocator: Allocator, path: []const u8, hash: ArtifactHash) !void {
        return self.setCleanFileWithMode(allocator, path, hash, .regular);
    }

    pub fn setCleanFileWithMode(
        self: *TreeManifest,
        allocator: Allocator,
        path: []const u8,
        hash: ArtifactHash,
        mode: FileMode,
    ) !void {
        if (hashEql(hash, ABSENT_HASH)) {
            const norm = try validateAndNormalizePath(allocator, path);
            defer allocator.free(norm);
            self.removePath(allocator, norm);
            return;
        }
        const sum = try PathSum.fromClean(allocator, hash);
        try self.setPathSumWithModeOwned(allocator, path, sum, mode);
    }

    pub fn removePath(self: *TreeManifest, allocator: Allocator, path: []const u8) void {
        const res = self.findEntryIndex(path);
        if (res.found) {
            var e = self.entries.orderedRemove(res.index);
            allocator.free(e.path);
            e.sum.deinit(allocator);
        }
    }

    /// Takes unconditional ownership of `sum_in` (deinitializing it on any error or clean-absent removal).
    pub fn setPathSumOwned(self: *TreeManifest, allocator: Allocator, path: []const u8, sum_in: PathSum) !void {
        return self.setPathSumWithModeOwned(allocator, path, sum_in, .regular);
    }

    pub fn setPathSumWithModeOwned(
        self: *TreeManifest,
        allocator: Allocator,
        path: []const u8,
        sum_in: PathSum,
        mode: FileMode,
    ) !void {
        var sum = sum_in;
        errdefer sum.deinit(allocator);

        sum.normalize();
        if (isValidNormalizedPath(path)) {
            if (sum.isAbsentClean()) {
                sum.deinit(allocator);
                self.removePath(allocator, path);
                return;
            }
            const res = self.findEntryIndex(path);
            if (res.found) {
                self.entries.items[res.index].sum.deinit(allocator);
                self.entries.items[res.index].sum = sum;
                self.entries.items[res.index].mode = mode;
                return;
            }
            const path_dup = try allocator.dupe(u8, path);
            errdefer allocator.free(path_dup);
            try self.entries.insert(allocator, res.index, .{
                .path = path_dup,
                .sum = sum,
                .mode = mode,
            });
            return;
        }

        const norm_path = try validateAndNormalizePath(allocator, path);
        errdefer allocator.free(norm_path);

        if (sum.isAbsentClean()) {
            sum.deinit(allocator);
            self.removePath(allocator, norm_path);
            allocator.free(norm_path);
            return;
        }

        const res = self.findEntryIndex(norm_path);
        if (res.found) {
            self.entries.items[res.index].sum.deinit(allocator);
            self.entries.items[res.index].sum = sum;
            self.entries.items[res.index].mode = mode;
            allocator.free(norm_path);
            return;
        }

        try self.entries.insert(allocator, res.index, .{
            .path = norm_path,
            .sum = sum,
            .mode = mode,
        });
    }

    pub fn sortEntries(self: *TreeManifest) void {
        if (self.entries.items.len <= 1) return;
        var already_sorted = true;
        for (1..self.entries.items.len) |idx| {
            if (std.mem.order(u8, self.entries.items[idx - 1].path, self.entries.items[idx].path) != .lt) {
                already_sorted = false;
                break;
            }
        }
        if (already_sorted) return;
        const Ctx = struct {
            pub fn lessThan(_: void, a: PathEntry, b: PathEntry) bool {
                return std.mem.order(u8, a.path, b.path) == .lt;
            }
        };
        std.mem.sort(PathEntry, self.entries.items, {}, Ctx.lessThan);
    }

    /// Compare `cand` against the virtual prefix `dir_prefix ++ "/"` without allocating.
    fn orderAgainstPrefixSlash(cand: []const u8, dir_prefix: []const u8) std.math.Order {
        const min_prefix = @min(cand.len, dir_prefix.len);
        const cmp = std.mem.order(u8, cand[0..min_prefix], dir_prefix[0..min_prefix]);
        if (cmp != .eq) return cmp;
        if (cand.len <= dir_prefix.len) return .lt;
        return std.math.order(cand[dir_prefix.len], '/');
    }

    /// Returns true if `path` is a regular file path that collides with a descendant path
    /// `path/...` in the same tree (a File-vs-Directory / D-F merge conflict) in O(log F) time.
    pub fn isFileShadowedBySubpath(self: TreeManifest, path: []const u8) bool {
        var lo: usize = 0;
        var hi: usize = self.entries.items.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            switch (orderAgainstPrefixSlash(self.entries.items[mid].path, path)) {
                .lt => lo = mid + 1,
                .gt, .eq => hi = mid,
            }
        }
        if (lo < self.entries.items.len) {
            const other = self.entries.items[lo].path;
            if (other.len > path.len and
                std.mem.startsWith(u8, other, path) and
                other[path.len] == '/')
            {
                return true;
            }
        }
        return false;
    }

    pub fn hasDirectoryFileConflicts(self: TreeManifest) bool {
        for (self.entries.items) |e| {
            if (self.isFileShadowedBySubpath(e.path)) return true;
        }
        return false;
    }

    pub fn hasConflicts(self: TreeManifest) bool {
        for (self.entries.items) |e| {
            if (e.sum.isConflicted()) return true;
        }
        return self.hasDirectoryFileConflicts();
    }

    /// Compute a deterministic BLAKE3 structural hash over all `(path, mode, terms)` in the tree.
    pub fn computeTreeHash(self: TreeManifest) ArtifactHash {
        var hasher = std.crypto.hash.Blake3.init(.{});
        hasher.update("ZIGVCS_TREE_V1\x00");
        for (self.entries.items) |e| {
            hasher.update(e.path);
            hasher.update("\x00");
            if (e.mode != .regular) {
                var mode_buf: [4]u8 = undefined;
                std.mem.writeInt(u32, &mode_buf, @intFromEnum(e.mode), .little);
                hasher.update(&mode_buf);
            }
            var count_buf: [4]u8 = undefined;
            std.mem.writeInt(u32, &count_buf, @intCast(e.sum.terms.items.len), .little);
            hasher.update(&count_buf);
            for (e.sum.terms.items) |t| {
                var coeff_buf: [4]u8 = undefined;
                std.mem.writeInt(i32, &coeff_buf, t.coeff, .little);
                hasher.update(&coeff_buf);
                hasher.update(&t.hash);
            }
        }
        var out: ArtifactHash = undefined;
        hasher.final(&out);
        return out;
    }

    pub fn eql(a: TreeManifest, b: TreeManifest) bool {
        if (a.entries.items.len != b.entries.items.len) return false;
        for (a.entries.items, b.entries.items) |ea, eb| {
            if (ea.mode != eb.mode) return false;
            if (!ea.sum.eql(eb.sum)) return false;
            if (!std.mem.eql(u8, ea.path, eb.path)) return false;
        }
        return true;
    }
};

/// Perform multi-path 3-way algebraic tree merge `B + C - A` in O(F) sorted-cursor time.
pub fn threeWayMergeTrees(
    allocator: Allocator,
    base: TreeManifest,
    ours: TreeManifest,
    theirs: TreeManifest,
) !TreeManifest {
    var merged: TreeManifest = .{};
    errdefer merged.deinit(allocator);

    const a_items = base.entries.items;
    const b_items = ours.entries.items;
    const c_items = theirs.entries.items;

    const max_cap = @max(a_items.len, @max(b_items.len, c_items.len));
    try merged.entries.ensureTotalCapacity(allocator, max_cap);

    var absent = try PathSum.fromAbsent(allocator);
    defer absent.deinit(allocator);

    var ia: usize = 0;
    var ib: usize = 0;
    var ic: usize = 0;

    while (ia < a_items.len or ib < b_items.len or ic < c_items.len) {
        var min_path: []const u8 = undefined;
        var has_min = false;

        if (ia < a_items.len) {
            min_path = a_items[ia].path;
            has_min = true;
        }
        if (ib < b_items.len) {
            if (!has_min or std.mem.order(u8, b_items[ib].path, min_path) == .lt) {
                min_path = b_items[ib].path;
                has_min = true;
            }
        }
        if (ic < c_items.len) {
            if (!has_min or std.mem.order(u8, c_items[ic].path, min_path) == .lt) {
                min_path = c_items[ic].path;
                has_min = true;
            }
        }

        const entry_a: ?PathEntry = if (ia < a_items.len and std.mem.eql(u8, a_items[ia].path, min_path)) blk: {
            const e = a_items[ia];
            ia += 1;
            break :blk e;
        } else null;

        const entry_b: ?PathEntry = if (ib < b_items.len and std.mem.eql(u8, b_items[ib].path, min_path)) blk: {
            const e = b_items[ib];
            ib += 1;
            break :blk e;
        } else null;

        const entry_c: ?PathEntry = if (ic < c_items.len and std.mem.eql(u8, c_items[ic].path, min_path)) blk: {
            const e = c_items[ic];
            ic += 1;
            break :blk e;
        } else null;

        const mode_a = if (entry_a) |e| e.mode else .regular;
        const mode_b = if (entry_b) |e| e.mode else .regular;
        const mode_c = if (entry_c) |e| e.mode else .regular;
        const merged_mode: FileMode = if (mode_b == mode_c)
            mode_b
        else if (mode_b == mode_a)
            mode_c
        else
            mode_b;

        // Fast-path 1 (Theorem 2): `ours == base` (`B == A`) => `B + C - A = C`
        const a_eq_b = if (entry_a != null and entry_b != null)
            entry_a.?.sum.eql(entry_b.?.sum)
        else
            (entry_a == null and entry_b == null);

        if (a_eq_b) {
            if (entry_c) |ec| {
                const p_dup = try allocator.dupe(u8, min_path);
                errdefer allocator.free(p_dup);
                const s_dup = try ec.sum.clone(allocator);
                try merged.entries.append(allocator, .{
                    .path = p_dup,
                    .sum = s_dup,
                    .mode = merged_mode,
                });
            }
            continue;
        }

        // Fast-path 2 (Theorem 3): `theirs == base` (`C == A`) => `B + C - A = B`
        const a_eq_c = if (entry_a != null and entry_c != null)
            entry_a.?.sum.eql(entry_c.?.sum)
        else
            (entry_a == null and entry_c == null);

        if (a_eq_c) {
            if (entry_b) |eb| {
                const p_dup = try allocator.dupe(u8, min_path);
                errdefer allocator.free(p_dup);
                const s_dup = try eb.sum.clone(allocator);
                try merged.entries.append(allocator, .{
                    .path = p_dup,
                    .sum = s_dup,
                    .mode = merged_mode,
                });
            }
            continue;
        }

        // General 2-sided modification case: compute `B + C - A` in `Z[A_bot]`
        const sum_a = if (entry_a) |e| e.sum else absent;
        const sum_b = if (entry_b) |e| e.sum else absent;
        const sum_c = if (entry_c) |e| e.sum else absent;

        var sum_m = try PathSum.threeWayMerge(allocator, sum_a, sum_b, sum_c);
        errdefer sum_m.deinit(allocator);
        if (sum_m.isAbsentClean()) {
            sum_m.deinit(allocator);
            continue;
        }
        const p_dup = try allocator.dupe(u8, min_path);
        errdefer allocator.free(p_dup);
        try merged.entries.append(allocator, .{
            .path = p_dup,
            .sum = sum_m,
            .mode = merged_mode,
        });
    }

    return merged;
}

test "TreeManifest (B + C - A): multi-path rebase conflict cancellation and same-change resolution" {
    const gpa = std.testing.allocator;

    const h_v1 = computeBlake3("v1");
    const h_v2 = computeBlake3("v2");
    const h_v3 = computeBlake3("v3");
    const h_v4 = computeBlake3("v4");

    var tree_a: TreeManifest = .{};
    defer tree_a.deinit(gpa);
    try tree_a.setCleanFile(gpa, "src/config.zig", h_v1);

    var tree_b: TreeManifest = .{};
    defer tree_b.deinit(gpa);
    try tree_b.setCleanFile(gpa, "src/config.zig", h_v2);

    var tree_c: TreeManifest = .{};
    defer tree_c.deinit(gpa);
    try tree_c.setCleanFile(gpa, "src/config.zig", h_v3);

    var tree_d: TreeManifest = .{};
    defer tree_d.deinit(gpa);
    try tree_d.setCleanFile(gpa, "src/config.zig", h_v4);

    // 1. Merge B and C over A => conflicted tree M = B + C - A
    var tree_m = try threeWayMergeTrees(gpa, tree_a, tree_b, tree_c);
    defer tree_m.deinit(gpa);
    try std.testing.expect(tree_m.hasConflicts());

    // 2. Rebase conflicted tree M from parent C onto D => M + D - C = B + D - A
    var rebased = try threeWayMergeTrees(gpa, tree_c, tree_m, tree_d);
    defer rebased.deinit(gpa);

    var direct_bd = try threeWayMergeTrees(gpa, tree_a, tree_b, tree_d);
    defer direct_bd.deinit(gpa);

    try std.testing.expect(rebased.eql(direct_bd));

    // 3. Rebase conflicted tree M onto B itself => M + B - C = B + C - A + B - C = 2*B - A -> collapses to clean B!
    var resolved_onto_b = try threeWayMergeTrees(gpa, tree_c, tree_m, tree_b);
    defer resolved_onto_b.deinit(gpa);
    try std.testing.expect(!resolved_onto_b.hasConflicts());
    try std.testing.expect(resolved_onto_b.eql(tree_b));
}
